const PUNCTUATION = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

class Scanner {
  constructor(input) {
    this.input = input
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
    this.errors = []
  }

  peek(offset = 0) {
    const idx = this.pos + offset
    if (idx >= this.input.length) return null
    return this.input[idx]
  }

  advance() {
    if (this.pos >= this.input.length) return null
    const char = this.input[this.pos]
    this.pos++

    if (char === '\n') {
      this.line++
      this.column = 1
    } else if (char === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }

    return char
  }

  skipWhitespace() {
    while (this.pos < this.input.length) {
      const char = this.peek()
      if (char === ' ' || char === '\t' || char === '\r' || char === '\n') {
        this.advance()
      } else {
        break
      }
    }
  }

  scanLineComment() {
    this.advance() // skip first /
    this.advance() // skip second /

    while (this.pos < this.input.length && this.peek() !== '\n') {
      this.advance()
    }
  }

  scanBlockComment() {
    const startLine = this.line
    const startColumn = this.column
    this.advance() // skip /
    this.advance() // skip *

    let depth = 1

    while (this.pos < this.input.length && depth > 0) {
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }

    if (depth > 0) {
      this.errors.push({
        line: startLine,
        column: startColumn,
        message: 'unterminated block comment'
      })
      return false
    }
    return true
  }

  scanString() {
    const startLine = this.line
    const startColumn = this.column
    this.advance() // skip opening quote

    let value = ''

    while (this.pos < this.input.length) {
      const char = this.peek()

      if (char === '"') {
        this.advance()
        return { kind: 'string', value, line: startLine, column: startColumn }
      }

      if (char === '\n') {
        this.errors.push({
          line: this.line,
          column: this.column,
          message: 'newline in string'
        })
        return null
      }

      if (char === '\\') {
        this.advance()
        const escaped = this.peek()

        if (escaped === 'n') {
          this.advance()
          value += '\n'
        } else if (escaped === 't') {
          this.advance()
          value += '\t'
        } else if (escaped === 'r') {
          this.advance()
          value += '\r'
        } else if (escaped === '\\') {
          this.advance()
          value += '\\'
        } else if (escaped === '"') {
          this.advance()
          value += '"'
        } else if (escaped === '0') {
          this.advance()
          value += '\0'
        } else if (escaped === 'x') {
          this.advance()
          if (!isHexDigit(this.peek()) || !isHexDigit(this.peek(1))) {
            this.errors.push({
              line: this.line,
              column: this.column - 1,
              message: `invalid escape \\${escaped}`
            })
            return null
          }
          const hex = this.input[this.pos] + this.input[this.pos + 1]
          this.advance()
          this.advance()
          value += String.fromCharCode(parseInt(hex, 16))
        } else if (escaped === 'u') {
          this.advance()
          if (this.peek() !== '{') {
            this.errors.push({
              line: this.line,
              column: this.column - 1,
              message: `invalid escape \\u`
            })
            return null
          }
          this.advance()
          let hex = ''
          while (this.pos < this.input.length && this.peek() !== '}') {
            if (!isHexDigit(this.peek())) {
              this.errors.push({
                line: this.line,
                column: this.column,
                message: `invalid escape \\u{`
              })
              return null
            }
            hex += this.peek()
            this.advance()
          }
          if (this.pos >= this.input.length) {
            this.errors.push({
              line: this.line,
              column: this.column,
              message: `invalid escape \\u{`
            })
            return null
          }
          if (hex.length === 0) {
            this.errors.push({
              line: this.line,
              column: this.column,
              message: `invalid escape \\u{`
            })
            return null
          }
          const codePoint = parseInt(hex, 16)
          if (codePoint > 0x10FFFF) {
            this.errors.push({
              line: this.line,
              column: this.column,
              message: `invalid escape \\u{`
            })
            return null
          }
          this.advance() // skip }
          value += String.fromCodePoint(codePoint)
        } else {
          this.errors.push({
            line: this.line,
            column: this.column - 1,
            message: `invalid escape \\${escaped}`
          })
          return null
        }
      } else {
        value += char
        this.advance()
      }
    }

    this.errors.push({
      line: startLine,
      column: startColumn,
      message: 'unterminated string'
    })
    return null
  }

  scanRawString() {
    const startLine = this.line
    const startColumn = this.column
    this.advance() // skip r
    this.advance() // skip opening quote

    let value = ''

    while (this.pos < this.input.length) {
      const char = this.peek()
      if (char === '"') {
        this.advance()
        return { kind: 'rawstring', value, line: startLine, column: startColumn }
      }
      value += char
      this.advance()
    }

    this.errors.push({
      line: startLine,
      column: startColumn,
      message: 'unterminated string'
    })
    return null
  }

