            if (!isHexDigit(this.peek(-1)) || !isHexDigit(this.peek(1))) {
              isValid = false
              text += this.advance()
              break
            }
            text += this.advance()
          } else {
            text += this.advance()
          }
        }
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      text += this.advance()
      text += this.advance()

