              line: this.line,
              column: this.column,
              message: `invalid escape \\u{`
            })
            return null
          }
          this.advance() // skip }
          value += String.fromCodePoint(codePoint)
        } else {
          this.errors.push({
            line: this.line,
            column: this.column - 1,
            message: `invalid escape \\${escaped}`
          })
          return null
        }
      } else {
        value += char
        this.advance()
      }
    }

    this.errors.push({
      line: startLine,
      column: startColumn,
      message: 'unterminated string'
    })
    return null
  }

  scanRawString() {
    const startLine = this.line
    const startColumn = this.column
    this.advance() // skip r
    this.advance() // skip opening quote

    let value = ''

    while (this.pos < this.input.length) {
      const char = this.peek()
      if (char === '"') {
        this.advance()
        return { kind: 'rawstring', value, line: startLine, column: startColumn }
      }
      value += char
      this.advance()
    }

    this.errors.push({
      line: startLine,
      column: startColumn,
      message: 'unterminated string'
    })
    return null
  }

  scanNumber() {
    const startLine = this.line
    const startColumn = this.column
    let text = ''
    let isValid = true

    // Check for hex, binary, octal
    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      text += this.advance()
      text += this.advance()

      if (!isHexDigit(this.peek())) {
        isValid = false
      } else {
        while (this.pos < this.input.length && (isHexDigit(this.peek()) || this.peek() === '_')) {
          if (this.peek() === '_') {
            // Check if _ is between two hex digits
            if (!isHexDigit(this.peek(-1)) || !isHexDigit(this.peek(1))) {
              isValid = false
              text += this.advance()
              break
            }
            text += this.advance()
          } else {
            text += this.advance()
          }
        }
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      text += this.advance()
      text += this.advance()

      if (this.peek() !== '0' && this.peek() !== '1') {
        isValid = false
      } else {
        while (this.pos < this.input.length && (this.peek() === '0' || this.peek() === '1' || this.peek() === '_')) {
          if (this.peek() === '_') {
            if ((this.peek(-1) !== '0' && this.peek(-1) !== '1') || (this.peek(1) !== '0' && this.peek(1) !== '1')) {
              isValid = false
              text += this.advance()
              break
            }
            text += this.advance()
          } else {
            text += this.advance()
          }
        }
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
      text += this.advance()
      text += this.advance()

      if (!isOctalDigit(this.peek())) {
        isValid = false
      } else {
        while (this.pos < this.input.length && (isOctalDigit(this.peek()) || this.peek() === '_')) {
          if (this.peek() === '_') {
            if (!isOctalDigit(this.peek(-1)) || !isOctalDigit(this.peek(1))) {
              isValid = false
              text += this.advance()
              break
            }
            text += this.advance()
          } else {
            text += this.advance()
          }
        }
      }
    } else {
      // Decimal number
      while (this.pos < this.input.length && (isDecimalDigit(this.peek()) || this.peek() === '_')) {
        if (this.peek() === '_') {
          if (!isDecimalDigit(this.peek(-1)) || !isDecimalDigit(this.peek(1))) {
            isValid = false
            text += this.advance()
            break
          }
          text += this.advance()
        } else {
          text += this.advance()
        }
      }

      // Check for decimal point
      if (isValid && this.peek() === '.' && isDecimalDigit(this.peek(1))) {
        text += this.advance()
        while (this.pos < this.input.length && (isDecimalDigit(this.peek()) || this.peek() === '_')) {
          if (this.peek() === '_') {
            if (!isDecimalDigit(this.peek(-1)) || !isDecimalDigit(this.peek(1))) {
              isValid = false
              text += this.advance()
              break
            }
            text += this.advance()
          } else {
            text += this.advance()
          }
        }
      }

      // Check for exponent
      if (isValid && (this.peek() === 'e' || this.peek() === 'E')) {
        const expStart = this.pos
        text += this.advance()

        if (this.peek() === '+' || this.peek() === '-') {
          text += this.advance()
        }

        if (!isDecimalDigit(this.peek())) {
          isValid = false
        } else {
          while (this.pos < this.input.length && (isDecimalDigit(this.peek()) || this.peek() === '_')) {
            if (this.peek() === '_') {
              if (!isDecimalDigit(this.peek(-1)) || !isDecimalDigit(this.peek(1))) {
                isValid = false
                text += this.advance()
                break
              }
              text += this.advance()
            } else {
              text += this.advance()
            }
          }
        }
      }
    }

    // Check for invalid trailing characters
    if (isDecimalDigit(this.peek()) || isLetter(this.peek()) || this.peek() === '_') {
      isValid = false
      text += this.advance()
    }

    if (!isValid) {
      this.errors.push({
        line: startLine,
        column: startColumn,
        message: `invalid number ${text}`
      })
      return null
    }

    return { kind: 'number', value: text, line: startLine, column: startColumn }
  }

  scanIdentifier() {
    const startLine = this.line
    const startColumn = this.column
    let text = ''

    while (this.pos < this.input.length && (isLetter(this.peek()) || isDecimalDigit(this.peek()) || this.peek() === '_')) {
      text += this.advance()
    }

    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, value: text, line: startLine, column: startColumn }
  }

  scanPunctuation() {
    const startLine = this.line
    const startColumn = this.column

    // Try longest match first
    for (const punct of PUNCTUATION) {
      let matches = true
      for (let i = 0; i < punct.length; i++) {
        if (this.peek(i) !== punct[i]) {
          matches = false
          break
        }
      }
      if (matches) {
        for (let i = 0; i < punct.length; i++) {
          this.advance()
        }
        return { kind: 'punct', value: punct, line: startLine, column: startColumn }
      }
    }

    return null
  }

  scan() {
    while (this.pos < this.input.length) {
      this.skipWhitespace()

      if (this.pos >= this.input.length) break

      const char = this.peek()
      const line = this.line
      const column = this.column

      // Check for comments
      if (char === '/' && this.peek(1) === '/') {
        this.scanLineComment()
        continue
      }

      if (char === '/' && this.peek(1) === '*') {
        if (!this.scanBlockComment()) {
          return false
        }
        continue
      }

      // Check for strings
      if (char === '"') {
        const token = this.scanString()
        if (!token) return false
        this.tokens.push(token)
        continue
      }

      // Check for raw strings
      if (char === 'r' && this.peek(1) === '"') {
        const token = this.scanRawString()
        if (!token) return false
        this.tokens.push(token)
        continue
      }

      // Check for numbers
      if (isDecimalDigit(char)) {
        const token = this.scanNumber()
        if (!token) return false
        this.tokens.push(token)
        continue
      }

      // Check for identifiers and keywords
      if (isLetter(char) || char === '_') {
        const token = this.scanIdentifier()
        this.tokens.push(token)
        continue
      }

      // Check for punctuation
      const token = this.scanPunctuation()
      if (token) {
        this.tokens.push(token)
        continue
      }

      // Unexpected character
      this.errors.push({
        line,
        column,
        message: `unexpected character ${char}`
      })
      return false
    }

    return true
  }
}

function isLetter(char) {
  if (!char) return false
  return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z')
}

function isDecimalDigit(char) {
  if (!char) return false
  return char >= '0' && char <= '9'
}

function isHexDigit(char) {
  if (!char) return false
  return (char >= '0' && char <= '9') || (char >= 'a' && char <= 'f') || (char >= 'A' && char <= 'F')
}

function isOctalDigit(char) {
  if (!char) return false
  return char >= '0' && char <= '7'
}

function escapeString(value) {
  let result = '"'
  for (const char of value) {
    if (char === '\n') result += '\\n'
    else if (char === '\t') result += '\\t'
    else if (char === '\r') result += '\\r'
    else if (char === '\\') result += '\\\\'
    else if (char === '"') result += '\\"'
    else if (char === '\0') result += '\\0'
    else if (char.charCodeAt(0) < 32 || char.charCodeAt(0) > 126) {
      const code = char.charCodeAt(0)
      result += `\\x${code.toString(16).padStart(2, '0')}`
    } else {
      result += char
    }
  }
  result += '"'
  return result
}

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read from stdin
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch (err) {
    // Handle error
  }

  const scanner = new Scanner(input)
  const success = scanner.scan()

  if (!success) {
    const error = scanner.errors[0]
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.message}\n`)
    process.exit(2)
  }

  if (mode === 'tokens') {
    for (const token of scanner.tokens) {
      let body = token.value
      if (token.kind === 'string') {
        body = escapeString(token.value)
      } else if (token.kind === 'rawstring') {
        body = escapeString(token.value)
      }
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${body}\n`)
    }
  } else {
    // stats mode
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0
    }

    for (const token of scanner.tokens) {
      counts[token.kind]++
    }

    let total = 0
    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      process.stdout.write(`${kind} ${counts[kind]}\n`)
      total += counts[kind]
    }
    process.stdout.write(`total ${total}\n`)
  }
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(1)
})

